fn vn(x:f32, z:f32, s:i32)->f32 {
  let xi=i32(floor(x)); let zi=i32(floor(z));
  let xf=x-floor(x); let zf=z-floor(z);
  let a=hashI(xi,zi,s); let b=hashI(xi+1,zi,s); let c=hashI(xi,zi+1,s); let d=hashI(xi+1,zi+1,s);
  let u2=xf*xf*(3.0-2.0*xf); let v2=zf*zf*(3.0-2.0*zf);
  return a+(b-a)*u2+(c-a)*v2+(a-b-c+d)*u2*v2;
}
fn valueNoise2(p:vec2f,s:i32)->f32{ return vn(p.x,p.y,s); }

fn vn3(x:vec3f)->f32 {
  let i=floor(x); var f=fract(x); f=f*f*f*(f*(f*6.0-15.0)+10.0);
  let n000=hash3(i); let n100=hash3(i+vec3f(1,0,0)); let n010=hash3(i+vec3f(0,1,0)); let n110=hash3(i+vec3f(1,1,0));
  let n001=hash3(i+vec3f(0,0,1)); let n101=hash3(i+vec3f(1,0,1)); let n011=hash3(i+vec3f(0,1,1)); let n111=hash3(i+vec3f(1,1,1));
  return mix(mix(mix(n000,n100,f.x),mix(n010,n110,f.x),f.y), mix(mix(n001,n101,f.x),mix(n011,n111,f.x),f.y), f.z);
}

fn grad2(ix:i32,iz:i32,s:i32)->vec2f{ let a=hashI(ix,iz,s)*6.2831853; return vec2f(cos(a),sin(a)); }
fn perlin2(p:vec2f,s:i32)->f32{
  let i=floor(p); let f=p-i; let u=f*f*f*(f*(f*6.0-15.0)+10.0);
  let ix=i32(i.x); let iz=i32(i.y);
  let g00=grad2(ix,iz,s); let g10=grad2(ix+1,iz,s); let g01=grad2(ix,iz+1,s); let g11=grad2(ix+1,iz+1,s);
  let d00=dot(g00,f); let d10=dot(g10,f-vec2f(1,0)); let d01=dot(g01,f-vec2f(0,1)); let d11=dot(g11,f-vec2f(1,1));
  return mix(mix(d00,d10,u.x),mix(d01,d11,u.x),u.y)*0.5+0.5;
}

fn simplex2(pin:vec2f,s:i32)->f32{
  let K1=0.366025404; let K2=0.211324865;
  let i=floor(pin+(pin.x+pin.y)*K1);
  let a=pin-i+(i.x+i.y)*K2;
  let o=select(vec2f(0.0,1.0),vec2f(1.0,0.0),a.x>a.y);
  let b=a-o+K2; let c=a-1.0+2.0*K2;
  var h=max(vec3f(0.5)-vec3f(dot(a,a),dot(b,b),dot(c,c)),vec3f(0.0)); h=h*h*h*h;
  let ii=i32(i.x); let jj=i32(i.y);
  let n=h.x*(hashI(ii,jj,s)*2.0-1.0)
      + h.y*(hashI(ii+i32(o.x),jj+i32(o.y),s)*2.0-1.0)
      + h.z*(hashI(ii+1,jj+1,s)*2.0-1.0);
  return clamp(n*35.0*0.5+0.5,0.0,1.0);
}

fn worley2(p:vec2f,s:i32)->vec2f{
  let g=floor(p); let f=p-g;
  var f1=8.0; var f2=8.0;
  for(var j=-1;j<=1;j++){ for(var i=-1;i<=1;i++){
    let o=vec2f(f32(i),f32(j));
    let fp=vec2f(hashI(i32(g.x)+i,i32(g.y)+j,s), hashI(i32(g.x)+i,i32(g.y)+j,s+7919));
    let d=length(o+fp-f);
    if(d<f1){ f2=f1; f1=d; } else if(d<f2){ f2=d; }
  }}
  return vec2f(f1,f2);
}

fn worley3(p:vec3f)->vec2f{
  let g=floor(p); let f=p-g;
  var f1=8.0; var f2=8.0;
  for(var k=-1;k<=1;k++){ for(var j=-1;j<=1;j++){ for(var i=-1;i<=1;i++){
    let o=vec3f(f32(i),f32(j),f32(k));
    let fp=fract(hash3(g+o)*vec3f(1.0,1.7,2.3)+0.5);
    let d=length(o+fp-f);
    if(d<f1){ f2=f1; f1=d; } else if(d<f2){ f2=d; }
  }}}
  return vec2f(f1,f2);
}

fn fbm2(p:vec2f, s:i32, oct:i32, scale:f32)->f32 {
  var f=0.0; var amp=0.5; var fr=1.0; var nm=0.0;
  for(var o=0;o<oct;o++){ f+=amp*vn(p.x*scale*fr, p.y*scale*fr, s+o*101); nm+=amp; amp=amp*0.5; fr=fr*2.0; }
  return f/nm;
}

fn ridged2(p:vec2f, s:i32, oct:i32, scale:f32)->f32 {
  var f=0.0; var amp=0.5; var fr=1.0; var prev=1.0;
  for(var o=0;o<oct;o++){ var r=1.0-abs(vn(p.x*scale*fr, p.y*scale*fr, s+o*101)*2.0-1.0); r=r*r;
    f+=amp*r*prev; prev=r; amp=amp*0.5; fr=fr*2.0; }
  return f;
}

fn billow2(p:vec2f, s:i32, oct:i32, scale:f32)->f32 {
  var f=0.0; var amp=0.5; var fr=1.0; var nm=0.0;
  for(var o=0;o<oct;o++){ let n=abs(vn(p.x*scale*fr,p.y*scale*fr,s+o*101)*2.0-1.0); f+=amp*n; nm+=amp; amp=amp*0.5; fr=fr*2.0; }
  return f/nm;
}

fn turbulence2(p:vec2f, s:i32, oct:i32, scale:f32)->f32 {
  var f=0.0; var amp=0.5; var fr=1.0; var nm=0.0;
  for(var o=0;o<oct;o++){ f+=amp*abs(vn(p.x*scale*fr,p.y*scale*fr,s+o*101)*2.0-1.0); nm+=amp; amp=amp*0.5; fr=fr*2.0; }
  return f/nm;
}

fn domainWarp(p:vec2f, s:i32, amp:f32, scale:f32)->vec2f {
  let qx=fbm2(p, s+11, 4, scale);
  let qz=fbm2(p+vec2f(5.2,1.3), s+29, 4, scale);
  return p + (vec2f(qx,qz)-0.5)*2.0*amp;
}

fn domainWarp3(p:vec3f, amp:f32)->vec3f {
  let qx=fbm3(p+vec3f(0.0,0.0,0.0),3);
  let qy=fbm3(p+vec3f(3.7,1.1,4.3),3);
  let qz=fbm3(p+vec3f(1.9,7.2,2.6),3);
  return p + (vec3f(qx,qy,qz)-0.5)*2.0*amp;
}

fn warpRecursive(p:vec2f, s:i32)->f32 {
  let q=vec2f(fbm2(p,s,4,1.0), fbm2(p+vec2f(5.2,1.3),s,4,1.0));
  let r=vec2f(fbm2(p+q*4.0+vec2f(1.7,9.2),s,4,1.0), fbm2(p+q*4.0+vec2f(8.3,2.8),s,4,1.0));
  return fbm2(p+r*4.0, s, 4, 1.0);
}

fn radialSym(p:vec2f, n:f32)->vec2f {
  var a=atan2(p.y,p.x); let r=length(p);
  let seg=6.2831853/n;
  a=abs(a - floor(a/seg+0.5)*seg);
  return vec2f(cos(a),sin(a))*r;
}

fn kaleido(p:vec2f, n:f32, twist:f32)->vec2f {
  var a=atan2(p.y,p.x); let r=length(p);
  let seg=6.2831853/n;
  a=a - floor(a/seg)*seg; a=abs(a-seg*0.5);
  a=a + twist*log(r+1.0);
  return vec2f(cos(a),sin(a))*r;
}

fn grad2f(p:vec2f, eps:f32)->vec2f {
  let hx=fbm2(p+vec2f(eps,0.0),1337,5,1.0)-fbm2(p-vec2f(eps,0.0),1337,5,1.0);
  let hz=fbm2(p+vec2f(0.0,eps),1337,5,1.0)-fbm2(p-vec2f(0.0,eps),1337,5,1.0);
  return vec2f(hx,hz)/(2.0*eps);
}

// heightAt is the generator being sampled; d is the finite-difference footprint
fn normalFromHeight(wx:f32, wz:f32, d:f32)->vec3f {
  let hl=heightAt(wx-d,wz,d); let hr=heightAt(wx+d,wz,d);
  let hd=heightAt(wx,wz-d,d); let hu=heightAt(wx,wz+d,d);
  return normalize(vec3f((hl-hr)/(2.0*d), 1.0, (hd-hu)/(2.0*d)));
}

fn curl2(p:vec2f, eps:f32)->vec2f {
  let n1=fbm2(p+vec2f(0.0,eps),733,4,1.0); let n2=fbm2(p-vec2f(0.0,eps),733,4,1.0);
  let n3=fbm2(p+vec2f(eps,0.0),733,4,1.0); let n4=fbm2(p-vec2f(eps,0.0),733,4,1.0);
  return vec2f((n1-n2)/(2.0*eps), -(n3-n4)/(2.0*eps));
}

fn downhill(wx:f32, wz:f32, d:f32)->vec2f {
  let hl=heightAt(wx-d,wz,d); let hr=heightAt(wx+d,wz,d);
  let hd=heightAt(wx,wz-d,d); let hu=heightAt(wx,wz+d,d);
  return -vec2f(hr-hl, hu-hd);
}

fn opU(a:f32,b:f32)->f32 { return min(a,b); }
fn opSub3(a:f32,b:f32)->f32 { return max(a,-b); }
fn opInter(a:f32,b:f32)->f32 { return max(a,b); }

// PING-PONG COMPUTE PASS (Gray-Scott). state: rg=(A,B) in a storage texture; run 20-100x per frame.
// bindings: src (read) A,B ; dst (write) A,B ; laplacian via 3x3 stencil.
fn rdStep(A:f32,B:f32,lapA:f32,lapB:f32,feed:f32,kill:f32,dA:f32,dB:f32)->vec2f {
  let react=A*B*B;
  let nA=A + (dA*lapA - react + feed*(1.0-A));
  let nB=B + (dB*lapB + react - (kill+feed)*B);
  return vec2f(clamp(nA,0.0,1.0), clamp(nB,0.0,1.0));
}

// PING-PONG COMPUTE PASS. state: r=alive 0/1. Conway/cave-gen (B678/S345678 for caves).
fn caStep(self:f32, neigh:i32, birthMask:u32, surviveMask:u32)->f32 {
  let alive=self>0.5;
  let b=(birthMask>>u32(neigh))&1u;
  let s=(surviveMask>>u32(neigh))&1u;
  if(alive){ return select(0.0,1.0,s==1u); }
  return select(0.0,1.0,b==1u);
}

// PING-PONG COMPUTE PASS over height+water+sediment grids. One droplet/virtual-pipe step:
fn erodeStep(h:f32, hDown:f32, sediment:f32, capacity:f32, deposit:f32, dissolve:f32)->vec2f {
  let slope=max(h-hDown,0.0);
  let cap=capacity*slope;
  let move=select(-dissolve*(cap-sediment), deposit*(sediment-cap), sediment>cap);
  return vec2f(h+move, sediment-move); // new height, new carried sediment
}

// PING-PONG COMPUTE PASS: each cell pushes its water to its lowest neighbour; accumulate over passes.
fn flowStep(myWater:f32, incoming:f32)->f32 { return myWater*0.02 + incoming; } // steady rain + upstream
// direction chosen by downhill(); after N passes high accum = river channels

// ATOMIC SCATTER/GATHER (from field_particle_join): particles carve & deposit fixed-point mass.
fn gather(cell:i32, dig:f32){ atomicSub(&depo[cell], i32(dig*FIXSCALE)); }
fn scatter(cell:i32, dig:f32){ atomicAdd(&depo[cell], i32(dig*FIXSCALE)); }
// resolve pass: h = height + depo/FIXSCALE; then h += (base-h)*clamp(heal*dt,0,1);

fn scatterMask(p:vec2f, density:f32, s:i32)->f32 {
  let cell=floor(p); let f=p-cell;
  let r0=hashI(i32(cell.x),i32(cell.y),s);
  if(r0>density){ return 0.0; }
  let jx=hashI(i32(cell.x),i32(cell.y),s+1); let jz=hashI(i32(cell.x),i32(cell.y),s+2);
  let d=length(f-vec2f(jx,jz));
  return 1.0-smoothstep(0.0,0.4,d);
}

fn stamp(p:vec2f, s:i32, cellScale:f32)->f32 {
  let g=p/cellScale; let cell=floor(g); let f=g-cell-0.5;
  let jx=hashI(i32(cell.x),i32(cell.y),s)-0.5;
  let jz=hashI(i32(cell.x),i32(cell.y),s+3)-0.5;
  let rot=hashI(i32(cell.x),i32(cell.y),s+7)*6.2831853;
  let local=rotate2(f-vec2f(jx,jz), rot);
  return length(local)-0.25; // replace with any SDF: stamps a jittered/rotated instance per cell
}

fn colorRamp(h:f32, slope:f32, sea:f32)->vec3f {
  let sand=vec3f(0.76,0.70,0.50); let grass=vec3f(0.22,0.44,0.16);
  let rock=vec3f(0.34,0.32,0.30); let snow=vec3f(0.92,0.94,0.97);
  var col=mix(sand,grass,smoothstep(sea+1.0,sea+22.0,h));
  col=mix(col,rock,smoothstep(260.0,440.0,h));
  col=mix(col,snow,smoothstep(520.0,760.0,h)*smoothstep(0.6,0.35,slope));
  col=mix(col,rock,smoothstep(0.40,0.7,slope));
  return col;
}

fn flowNoise(p:vec2f, t:f32, s:i32)->f32 {
  let flow=curl2(p*0.5, 0.01)*t*0.3;
  return fbm2(p+flow, s, 4, 1.0);
}
